type Mode = 'Today' | 'Blueprint' | 'Study Map' | 'Observations' | 'Experiments' | 'Playbook' | 'Routines + Habits' | 'System Map' | 'Evidence' | 'Progress' | 'Archive';
type Confidence = 'Source idea' | 'Trying' | 'Promising' | 'Works for me' | 'Retired';
type StudyArea = 'Identity' | 'Productivity' | 'Energy' | 'Mindset' | 'Digital Life' | 'Environment' | 'Relationships' | 'Career + Money' | 'Face' | 'Skin' | 'Hair' | 'Makeup' | 'Brows + Lashes' | 'Smile' | 'Body + Grooming' | 'Style' | 'Color + Contrast' | 'Posture + Presence' | 'Photos + Angles' | 'Expression + Voice';

type StudyNote = { id:string; createdAt:string; area:StudyArea; title:string; detail:string; source:string; confidence:Confidence; evidence:string; archived:boolean };
type Experiment = { id:string; createdAt:string; area:StudyArea; title:string; change:string; measure:string; result:string; status:'Planned'|'Testing'|'Complete' };
type MemoryState = { notes:StudyNote[]; experiments:Experiment[]; focusAreas:StudyArea[]; adoptedPackKeys:string[]; completedPackSteps:string[]; favoriteLook:string };
type SourceSection = { source:string; theme:string; points:string[] };
type HabitPack = { key:string; title:string; kind:'Routine'|'Habit pack'|'Review'|'Experiment'; frequency:string; purpose:string; steps:string[]; caution?:string; links:string[] };
type SystemUpgrade = { page:string; href:string; role:string; upgrades:string[] };

